3	```solidity
4	// SPDX-License-Identifier: MIT
5	pragma solidity ^0.8.28;
6	
7	/// @notice A sink that splits what it receives between a fixed table of beneficiaries, escrows the
8	/// shares it cannot push, and puts every change to itself behind one timelock.
9	/// @dev Deployed once as an implementation and used through PUSH0 clones. `factory` and `self` live
10	/// in the implementation's bytecode, so a clone reads the implementation's deployer and the
11	/// implementation's own address — which is how the implementation rejects ETH while a clone accepts it.
12	contract Distribution {
13	    struct Beneficiary {
14	        address account;
15	        uint96 bps;
16	        string name;
17	        string note;
18	    }
19	
20	    struct Pending {
21	        bytes32 hash;
22	        uint256 eta;
23	        bytes action;
24	    }
25	
26	    struct Snapshot {
27	        address owner;
28	        uint32 delay;
29	        uint32 nonce;
30	        string description;
31	        Beneficiary[] table;
32	        Pending[] pending;
33	    }
34	
35	    event Received(address indexed from, uint256 amount);
36	    event Distributed(address indexed token, uint256 amount);
37	    event Escrowed(address indexed token, address indexed account, uint256 amount);
38	    event Released(address indexed token, address indexed account, uint256 amount);
39	    event Claimed(address indexed token, address indexed account, address to, uint256 amount);
40	    event Queued(bytes32 indexed hash, uint32 nonce, uint256 eta, bytes action);
41	    event Applied(bytes32 indexed hash);
42	    event Cancelled(bytes32 indexed hash);
43	
44	    /// @dev Ownable2Step's name and shape. Emitted on acceptance and on a renounce: the nomination
45	    /// already rides in `Queued`'s calldata, so without this a log reader sees "B was nominated" and
46	    /// never "B took it" — the one state change in the contract with no trace of its own. A renounce
47	    /// is the other, and it emits `newOwner == address(0)`.
48	    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
49	
50	    error NotOwner();
51	    error BadTable();
52	    error NotReady(uint256 eta);
53	    error NothingToDo();
54	    error Locked();
55	    error Unauthorized();
56	    error ReleaseFailed(address token);
57	    error Expired(uint256 eta);
58	
59	    /// @dev Measured in m03-t01 (`test/PushGas.t.sol`, cold): a Safe v1.4.1 proxy receives in 4,029
60	    /// gas and a multisig.software vault clone in 404, so 100_000 is 23x the larger need and was kept
61	    /// under decision 30.
62	    uint256 private constant PUSH_GAS = 100_000;
63	    uint256 private constant BPS_TOTAL = 10_000;
64	
65	    /// @notice How long after its eta a matured action stays applicable. Past it, `applyQueued`
66	    /// reverts `Expired` and anyone may `cancel` the entry. Compound's Timelock shape: a change nobody
67	    /// applied inside the window lapses instead of waiting as a permanent option held by the public.
68	    uint256 public constant GRACE = 14 days;
69	
70	    /// @dev Measured in m03-t01 (`test/TableCap.t.sol`): a worst-case row, where the recipient burns
71	    /// the whole push cap and then fails, costs 138,917 gas, so 107 rows distribute in 14,896,325 and
72	    /// 108 need 15,035,242. The rule enforced is that a worst-case `distribute` stays under half a
73	    /// 30M block. Those three figures are of the tree t01 measured, `main` at `b055bc3`; re-measure
74	    /// rather than quote them.
75	    uint256 public constant MAX_BENEFICIARIES = 107;
76	    bytes4 private constant TRANSFER = 0xa9059cbb;
77	    bytes4 private constant BALANCE_OF = 0x70a08231;
78	
79	    address public owner;
80	    uint32 public delay;
81	    uint32 public nonce;
82	
83	    /// @dev After `nonce`, not after `owner`: `owner`, `delay` and `nonce` pack into one slot and a
84	    /// 20-byte address cannot join them, so placing it here leaves that slot whole and `propose` and
85	    /// `snapshot` keep their single read of it.
86	    address public pendingOwner;
87	    string public description;
88	
89	    /// @dev Stored in the order given, which table validation forces to be ascending by account.
90	    Beneficiary[] private _table;
91	    Pending[] private _pending;
92	    /// @dev 1-based index into `_pending`; 0 means absent.
93	    mapping(bytes32 => uint256) private _pendingIndex;
94	
95	    /// @notice Queued action hash to the timestamp it becomes applicable.
96	    mapping(bytes32 => uint256) public queued;
97	    /// @notice Token (0 for ETH) to the total this contract holds on behalf of failed pushes.
98	    mapping(address => uint256) public reserved;
99	    /// @notice Token (0 for ETH) to account to the amount escrowed for it.
100	    mapping(address => mapping(address => uint256)) public escrowed;
101	
102	    bool private transient locked;
103	
104	    address private immutable factory;
105	    address private immutable self;
106	
107	    constructor() {
108	        factory = msg.sender;
109	        self = address(this);
110	    }
111	
112	    modifier nonReentrant() {
113	        if (locked) revert Locked();
114	        locked = true;
115	        _;
116	        locked = false;
117	    }
118	
119	    /// @dev Refuses entry while a money path holds the lock; does not take it. A configuration change
120	    /// landing between two rows of `distribute` would pay the rest from a table nobody has seen.
121	    modifier notLocked() {
122	        if (locked) revert Locked();
123	        _;
124	    }
125	
126	    /// @dev The timelock reaches state only through a self-call, so every mutator is `onlySelf`.
127	    modifier onlySelf() {
128	        if (msg.sender != address(this)) revert Unauthorized();
129	        _;
130	    }
131	
132	    /// @notice Initialise a clone. Callable once, by whoever deployed the implementation. Any value
133	    /// present at this point is logged as `Received(address(0), balance)` — the sentinel for "present
134	    /// at init, sender unknown" — which covers both value that rode the `create` and value sent to the
135	    /// counterfactual address before any code existed there. Forced sends after deployment stay
136	    /// unlogged; `docs/REFERENCE.md` says so.
137	    function init(address owner_, uint32 delay_, string calldata description_, Beneficiary[] calldata table_)
138	        external
139	        payable
140	    {
141	        if (msg.sender != factory || _table.length != 0) revert Unauthorized();
142	        owner = owner_;
143	        delay = delay_;
144	        description = description_;
145	        _set(table_);
146	        if (address(this).balance != 0) emit Received(address(0), address(this).balance);
147	    }
148	
149	    /// @dev Must run under a 2,300-gas `transfer` stipend, so it does nothing but the guard and the log.
150	    receive() external payable {
151	        if (address(this) == self) revert Unauthorized();
152	        emit Received(msg.sender, msg.value);
153	    }
154	
155	    /// @notice Split everything not already escrowed between the table, in table order.
156	    /// @param token The ERC-20 to split, or `address(0)` for ETH.
157	    function distribute(address token) external nonReentrant {
158	        uint256 amount = _balance(token) - reserved[token];
159	        if (amount == 0) revert NothingToDo();
160	
161	        uint256 n = _table.length;
162	        uint256 paid;
163	        for (uint256 i; i < n; ++i) {
164	            Beneficiary storage b = _table[i];
165	            // The last row takes the remainder, so the shares always sum to `amount`.
166	            uint256 share = i + 1 == n ? amount - paid : (uint256(b.bps) * amount) / BPS_TOTAL;
167	            paid += share;
168	            address account = b.account;
169	            (bool ok,) = _push(token, account, share, false);
170	            if (!ok) {
171	                escrowed[token][account] += share;
172	                reserved[token] += share;
173	                emit Escrowed(token, account, share);
174	            }
175	        }
176	        emit Distributed(token, amount);
177	    }
178	
179	    /// @notice Retry the escrowed amount for one account. Reverts if the retry fails, leaving the escrow.
180	    function release(address token, address account) external nonReentrant {
181	        uint256 amount = escrowed[token][account];
182	        if (amount == 0) revert NothingToDo();
183	
184	        escrowed[token][account] = 0;
185	        reserved[token] -= amount;
186	        (bool ok, bytes memory data) = _push(token, account, amount, true);
187	        // A word or less is the bare `false` of a non-reverting token, empty revert data, or an
188	        // argument-less custom error: no reason worth bubbling, so name the failure instead
189	        // (decision 24). Anything longer carries its own reason and keeps it.
190	        if (!ok) {
191	            if (data.length <= 32) revert ReleaseFailed(token);
192	            _bubble(data);
193	        }
194	        emit Released(token, account, amount);
195	    }
196	
197	    /// @notice The escrowed account takes its own escrow, to an address it names, with the caller's
198	    /// gas: no `PUSH_GAS` cap, because the beneficiary is paying for its own receive. Only
199	    /// `msg.sender`'s escrow moves, so neither the owner nor anyone else gains a path to funds.
200	    /// @param token The escrowed ERC-20, or `address(0)` for ETH.
201	    /// @param to Where to send it. Not validated: it is the beneficiary's own money.
202	    function claim(address token, address to) external nonReentrant {
203	        uint256 amount = escrowed[token][msg.sender];
204	        if (amount == 0) revert NothingToDo();
205	
206	        escrowed[token][msg.sender] = 0;
207	        reserved[token] -= amount;
208	        bool ok;
209	        bytes memory data;
210	        if (token == address(0)) (ok, data) = to.call{value: amount}("");
211	        else (ok, data) = _push(token, to, amount, true);
212	        // `release`'s failure path (decision 24): a word or less is named, a longer reason bubbles.
213	        if (!ok) {
214	            if (data.length <= 32) revert ReleaseFailed(token);
215	            _bubble(data);
216	        }
217	        emit Claimed(token, msg.sender, to, amount);
218	    }
219	
220	    /// @notice Queue a self-call, or run it now when `delay` is zero. Refused while `distribute` or
221	    /// `release` is running.
222	    /// @param action Calldata for one of this contract's `onlySelf` functions.
223	    function propose(bytes calldata action) external notLocked returns (bytes32 hash) {
224	        if (msg.sender != owner) revert NotOwner();
225	
226	        uint32 n = ++nonce;
227	        hash = keccak256(abi.encode(action, n));
228	        uint32 d = delay;
229	        if (d == 0) {
230	            emit Queued(hash, n, block.timestamp, action);
231	            _selfCall(action);
232	            emit Applied(hash);
233	        } else {
234	            uint256 eta = block.timestamp + d;
235	            queued[hash] = eta;
236	            _pendingIndex[hash] = _pending.length + 1;
237	            _pending.push(Pending({hash: hash, eta: eta, action: action}));
238	            emit Queued(hash, n, eta, action);
239	        }
240	    }
241	
242	    /// @notice Run a queued action once its eta has passed, and only until `GRACE` after it: past that
243	    /// the action has expired, this reverts `Expired`, and anyone may `cancel` the entry. A failing
244	    /// action stays queued for a retry. Refused while `distribute` or `release` is running.
245	    function applyQueued(bytes calldata action, uint32 nonce_) external notLocked {
246	        bytes32 hash = keccak256(abi.encode(action, nonce_));
247	        uint256 eta = queued[hash];
248	        // A timelock is a timestamp comparison; a validator's few seconds of drift is not the threat.
249	        // forge-lint: disable-next-line(block-timestamp)
250	        if (eta == 0 || block.timestamp < eta) revert NotReady(eta);
251	        // forge-lint: disable-next-line(block-timestamp)
252	        if (block.timestamp > eta + GRACE) revert Expired(eta);
253	
254	        delete queued[hash];
255	        _remove(hash);
256	        _selfCall(action);
257	        emit Applied(hash);
258	    }
259	
260	    /// @notice Drop a queued action. Immediate: the delay guards applying, not cancelling. The owner's
261	    /// while the action can still be applied; once it has expired — more than `GRACE` after its eta —
262	    /// anyone may drop it, so a renounced or inattentive owner cannot leave the queue uncleanable.
263	    function cancel(bytes32 hash) external {
264	        uint256 eta = queued[hash];
265	        // Anyone may drop an expired action; everything else stays the owner's. This order matters:
266	        // a non-owner must still see `NotOwner` for an entry that does not exist or has not expired,
267	        // which checking `NothingToDo` first would turn into `NothingToDo`.
268	        // forge-lint: disable-next-line(block-timestamp)
269	        if (msg.sender != owner && (eta == 0 || block.timestamp <= eta + GRACE)) revert NotOwner();
270	        if (eta == 0) revert NothingToDo();
271	
272	        delete queued[hash];
273	        _remove(hash);
274	        emit Cancelled(hash);
275	    }
276	
277	    function setBeneficiaries(Beneficiary[] calldata table_) external onlySelf {
278	        _set(table_);
279	    }
280	
281	    function setDescription(string calldata description_) external onlySelf {
282	        description = description_;
283	    }
284	
285	    function setDelay(uint32 delay_) external onlySelf {
286	        delay = delay_;
287	    }
288	
289	    /// @notice Name the next owner, who must call `acceptOwnership()` before anything changes; until
290	    /// then the current owner keeps every power. `address(0)` renounces at once — nothing can be
291	    /// proposed again, it drops every queued action, and it emits `OwnershipTransferred(owner,
292	    /// address(0))`, so a renounce leaves the same trace a handover does — and drops any pending
293	    /// transfer with it. Naming the current owner withdraws a pending transfer.
294	    function transferOwnership(address owner_) external onlySelf {
295	        if (owner_ == address(0)) {
296	            emit OwnershipTransferred(owner, address(0));
297	            owner = address(0);
298	            pendingOwner = address(0);
299	            _clearQueue();
300	            return;
301	        }
302	        pendingOwner = owner_ == owner ? address(0) : owner_;
303	    }
304	
305	    /// @notice Take ownership after the owner named you with `transferOwnership`, and drops every
306	    /// action the previous owner queued.
307	    function acceptOwnership() external {
308	        if (msg.sender != pendingOwner) revert Unauthorized();
309	
310	        emit OwnershipTransferred(owner, msg.sender);
311	        owner = msg.sender;
312	        pendingOwner = address(0);
313	        _clearQueue();
314	    }
315	
316	    /// @notice Everything a reader needs in one call.
317	    function snapshot() external view returns (Snapshot memory) {
318	        return Snapshot({
319	            owner: owner, delay: delay, nonce: nonce, description: description, table: _table, pending: _pending
320	        });
321	    }
322	
323	    /// @dev Not `table()`: forge reserves the `table` prefix for table tests and fails the suite.
324	    function beneficiaries() external view returns (Beneficiary[] memory) {
325	        return _table;
326	    }
327	
328	    function pendingCount() external view returns (uint256) {
329	        return _pending.length;
330	    }
331	
332	    /// @dev Ascending accounts make duplicates impossible and keep the first row above `address(0)`.
333	    function _set(Beneficiary[] calldata table_) private {
334	        uint256 n = table_.length;
335	        if (n == 0 || n > MAX_BENEFICIARIES) revert BadTable();
336	
337	        delete _table;
338	        uint256 sum;
339	        address prev;
340	        for (uint256 i; i < n; ++i) {
341	            Beneficiary calldata b = table_[i];
342	            if (b.bps == 0 || b.account <= prev) revert BadTable();
343	            prev = b.account;
344	            sum += b.bps;
345	            _table.push(b);
346	        }
347	        if (sum != BPS_TOTAL) revert BadTable();
348	    }
349	
350	    /// @dev Drops every queued action, newest first, emitting `Cancelled` for each so a log reader's
351	    /// pending list empties the way it would have by hand. Runs on a handover and on a renounce:
352	    /// what the previous owner queued was queued under an authority that no longer exists.
353	    function _clearQueue() private {
354	        uint256 n = _pending.length;
355	        while (n > 0) {
356	            bytes32 hash = _pending[--n].hash;
357	            delete queued[hash];
358	            delete _pendingIndex[hash];
359	            _pending.pop();
360	            emit Cancelled(hash);
361	        }
362	    }
363	
364	    /// @dev Swap-and-pop, so `_pending` stays iterable and the surviving order is stable otherwise.
365	    function _remove(bytes32 hash) private {
366	        uint256 i = _pendingIndex[hash];
367	        if (i == 0) return;
368	
369	        uint256 last = _pending.length;
370	        if (i != last) {
371	            Pending storage moved = _pending[last - 1];
372	            _pending[i - 1] = moved;
373	            _pendingIndex[moved.hash] = i;
374	        }
375	        _pending.pop();
376	        delete _pendingIndex[hash];
377	    }
378	
379	    function _selfCall(bytes calldata action) private {
380	        (bool ok, bytes memory data) = address(this).call(action);
381	        if (!ok) _bubble(data);
382	    }
383	
384	    /// @dev A token with no code returns nothing here, which does not decode — so it fails.
385	    function _balance(address token) private view returns (uint256) {
386	        if (token == address(0)) return address(this).balance;
387	
388	        (bool ok, bytes memory data) = token.staticcall(abi.encodeWithSelector(BALANCE_OF, address(this)));
389	        if (!ok) _bubble(data);
390	        return abi.decode(data, (uint256));
391	    }
392	
393	    /// @dev ETH is capped so one hostile recipient cannot burn the whole distribution; an ERC-20 push
394	    /// is bounded by the token. A no-return token (mainnet USDT) counts as success; anything else must
395	    /// answer with a word equal to one, decoded as a `uint256` so hostile return data cannot revert here.
396	    ///
397	    /// `keepData` buys the ETH branch's return data. `distribute` passes false and calls with a
398	    /// zero-length output area, so a recipient reverting with megabytes costs it one `RETURNDATASIZE`
399	    /// it never reads instead of the memory to hold them — unbounded copying inside the loop broke the
400	    /// half-block property decision 27 rests on at about eleven hostile rows. `release` passes true,
401	    /// because decision 24 bubbles a reason longer than a word and cannot name one it did not copy.
402	    /// The ERC-20 branch ignores the flag: it needs the return word below, and the token is the one
403	    /// `distribute(token)` was called with, so a hostile token's return data costs only the caller who
404	    /// named it.
405	    function _push(address token, address to, uint256 amount, bool keepData)
406	        private
407	        returns (bool ok, bytes memory data)
408	    {
409	        if (token == address(0)) {
410	            if (keepData) {
411	                (ok, data) = to.call{value: amount, gas: PUSH_GAS}("");
412	            } else {
413	                uint256 gasCap = PUSH_GAS;
414	                assembly ("memory-safe") {
415	                    ok := call(gasCap, to, amount, 0, 0, 0, 0)
416	                }
417	            }
418	            return (ok, data);
419	        }
420	        (ok, data) = token.call(abi.encodeWithSelector(TRANSFER, to, amount));
421	        ok = ok && (data.length == 0 || (data.length >= 32 && abi.decode(data, (uint256)) == 1));
422	    }
423	
424	    function _bubble(bytes memory data) private pure {
425	        assembly ("memory-safe") {
426	            revert(add(data, 0x20), mload(data))
427	        }
428	    }
429	}
430	
431	/// @notice Deploys `Distribution` clones to an address that depends on this factory and a salt alone.
432	/// @dev No `receive` and no `fallback`, so ETH sent to the factory itself reverts; the implementation
433	/// rejects it too. Clones are PUSH0 minimal proxies placed with CREATE2, so the same factory reaches
434	/// the same clone address on every chain.
435	contract DistributionFactory {
436	    event Created(address indexed distribution, address indexed owner);
437	
438	    error DeploymentFailed();
439	    error SaltDoesNotStartWith();
440	
441	    /// @dev Deployed by the factory, so `Distribution.factory` is this contract on every clone.
442	    address public immutable implementation = address(new Distribution{salt: bytes32(0)}());
443	
444	    /// @notice Deploy and initialise a clone at `predict(salt)`.
445	    /// @param salt Its top 20 bytes must equal `msg.sender`. `msg.value` rides the CREATE2, so a
446	    /// deposit lands in the clone without a `Received` log.
447	    /// @dev Three properties the dapp has to know about this address:
448	    /// 1. It depends on this factory and `salt` only — not on the owner, delay, description or table.
449	    ///    So the sender fixes the address; the owner does not enter it. One EOA calls `create` with
450	    ///    the same salt on every chain and passes the vault as `owner_`, and the clone is owned by
451	    ///    that vault from its first block at one address, with no ownership transfer ever needed.
452	    ///    Each chain is a separate contract: transferring ownership on one changes neither the salt
453	    ///    nor any other chain, so the deploying key never needs to own anything.
454	    /// 2. A second `create` with a used salt burns the whole gas limit before `DeploymentFailed`: a
455	    ///    CREATE2 collision consumes every unit forwarded to it. Read `predict(salt)` with
456	    ///    `eth_getCode` first and refuse a non-empty answer.
457	    /// 3. Same-address-everywhere is this factory's address, not a clone's claim on its own. The
458	    ///    factory is nonce-addressed where it is deployed; a byte-identical deploy through a
459	    ///    deterministic deployer is a later milestone's one-way door.
460	    function create(
461	        address owner_,
462	        uint32 delay_,
463	        string calldata description_,
464	        Distribution.Beneficiary[] calldata table_,
465	        bytes32 salt
466	    ) external payable returns (address distribution) {
467	        address impl = implementation;
468	        uint256 prefix = uint256(salt) >> 96;
469	        if (prefix != uint256(uint160(msg.sender))) revert SaltDoesNotStartWith();
470	
471	        // The PUSH0 minimal-proxy init code, byte for byte as solady's `LibClone.initCode_PUSH0`
472	        // writes it. The two `mstore`s at 0x24 overlap the free memory pointer and restore it.
473	        assembly ("memory-safe") {
474	            mstore(0x24, 0x5af43d5f5f3e6029573d5ffd5b3d5ff3)
475	            mstore(0x14, impl)
476	            mstore(0x00, 0x602d5f8160095f39f35f5f365f5f37365f73)
477	            distribution := create2(callvalue(), 0x0e, 0x36, salt)
478	            if iszero(distribution) {
479	                mstore(0x00, 0x30116425) // DeploymentFailed()
480	                revert(0x1c, 0x04)
481	            }
482	            mstore(0x24, 0)
483	        }
484	        Distribution(payable(distribution)).init(owner_, delay_, description_, table_);
485	        emit Created(distribution, owner_);
486	    }
487	
488	    /// @notice The address `create(..., salt)` would reach.
489	    /// @dev No prefix check: the dapp predicts before it knows who will send.
490	    function predict(bytes32 salt) external view returns (address) {
491	        address impl = implementation;
492	        bytes32 initCodeHash;
493	        assembly ("memory-safe") {
494	            mstore(0x24, 0x5af43d5f5f3e6029573d5ffd5b3d5ff3)
495	            mstore(0x14, impl)
496	            mstore(0x00, 0x602d5f8160095f39f35f5f365f5f37365f73)
497	            initCodeHash := keccak256(0x0e, 0x36)
498	            mstore(0x24, 0)
499	        }
500	        return address(uint160(uint256(keccak256(abi.encodePacked(hex"ff", address(this), salt, initCodeHash)))));
501	    }
502	}
503	
