508	```solidity
509	// SPDX-License-Identifier: MIT
510	pragma solidity ^0.8.26;
511	
512	import {Ownable} from "solady/auth/Ownable.sol";
513	import {SSTORE2} from "solady/utils/SSTORE2.sol";
514	import {Base64} from "solady/utils/Base64.sol";
515	
516	/// @title App
517	/// @notice The dapp and its embeddable widget, hosted by this contract.
518	///         ERC-8244: `html()` returns the whole document.
519	///         ERC-5219 / ERC-6944: `request()` serves "/" with a text/html header so web3:// gateways
520	///         render it at the root, and `request(["widget.js"])` the widget as application/javascript.
521	/// @dev Two resources, two pointer lists: `chunks` for the dapp and `widgetChunks` for the widget.
522	///      Each document lives in SSTORE2 chunks, concatenated at read time. If `gzipped`, `html()` wraps
523	///      the base64 payload in a bootstrap that inflates it client-side with DecompressionStream. The
524	///      widget is served raw and never wrapped: a `<script src="widget.js">` fetched through a gateway
525	///      must be plain JavaScript, and the bootstrap is an HTML document a script tag cannot run.
526	///      `lock()` freezes both lists; it requires the dapp and does not require a widget.
527	contract App is Ownable {
