641	    function addWidgetChunk(bytes calldata data) external onlyOwner returns (address ptr) {
642	        if (locked) revert Locked();
643	        ptr = SSTORE2.write(data);
644	        widgetChunks.push(ptr);
645	        emit WidgetChunksSet(widgetChunks.length);
646	    }
