648	    /// @notice Replace the whole widget pointer list. No gzip flag: the widget is always raw.
649	    /// @dev These pointers arrive from calldata, unlike `addWidgetChunk`'s, so each must hold code.
650	    function setWidgetChunks(address[] calldata ptrs) external onlyOwner {
651	        if (locked) revert Locked();
652	        if (ptrs.length == 0) revert EmptyDocument();
653	        delete widgetChunks;
654	        for (uint256 i; i < ptrs.length; ++i) {
