653	        delete widgetChunks;
654	        for (uint256 i; i < ptrs.length; ++i) {
655	            _requireChunk(ptrs[i]);
656	            widgetChunks.push(ptrs[i]);
657	        }
658	        emit WidgetChunksSet(ptrs.length);
659	    }
660	
661	    function setVersion(string calldata v) external onlyOwner {
662	        if (locked) revert Locked();
663	        version = v;
664	        emit VersionSet(v);
665	    }
666	
667	    /// @notice Freeze both documents permanently. One-way.
668	    /// @dev Re-checks that the documents are readable rather than trusting `setChunks`: a one-way door
669	    ///      should not depend on a guarantee stated in another function. Not an `html()` call, which
670	    ///      is unbounded gas and would fail for size rather than correctness. The emptiness check is
671	    ///      the dapp's alone: a dapp with no widget is a complete document, and the widget's own
672	    ///      pointers are still checked for code so a locked `App` cannot carry an unreadable one.
673	    ///      The re-check is for a readable *chunk* and not merely for code, because a pointer that
674	    ///      holds code that is not a chunk is the thing the lock must refuse: its bytes can still
675	    ///      change afterwards, which is exactly the promise `lock()` exists to make.
676	    function lock() external onlyOwner {
677	        uint256 n = chunks.length;
678	        if (n == 0) revert EmptyDocument();
679	        for (uint256 i; i < n; ++i) {
680	            _requireChunk(chunks[i]);
681	        }
682	        uint256 w = widgetChunks.length;
683	        for (uint256 i; i < w; ++i) {
684	            _requireChunk(widgetChunks[i]);
685	        }
686	        locked = true;
687	        emit AppLocked();
688	    }
689	
690	    function chunkCount() external view returns (uint256) {
691	        return chunks.length;
692	    }
693	
694	    function widgetChunkCount() external view returns (uint256) {
695	        return widgetChunks.length;
696	    }
697	
698	    function _raw(address[] storage list) internal view returns (bytes memory out) {
699	        uint256 n = list.length;
700	        for (uint256 i; i < n; ++i) {
701	            out = bytes.concat(out, SSTORE2.read(list[i]));
702	        }
703	    }
704	
705	    /// @dev Reverts unless `ptr` is a readable SSTORE2 chunk: non-empty code whose first byte is 0x00.
706	    function _requireChunk(address ptr) private view {
707	        uint256 n;
708	        bytes32 first;
709	        /// @solidity memory-safe-assembly
710	        assembly {
711	            n := extcodesize(ptr)
712	            extcodecopy(ptr, 0x00, 0x00, 0x01)
713	            first := mload(0x00)
714	        }
715	        if (n == 0) revert CodelessChunk(ptr);
716	        if (first[0] != 0x00) revert ForeignChunk(ptr);
717	    }
718	
719	    function _eq(string memory a, string memory b) private pure returns (bool) {
720	        return keccak256(bytes(a)) == keccak256(bytes(b));
721	    }
722	}
